40	    // ---------- 主流程 ----------
41	
42	    @Test
43	    void createDraftThenGetDetail() throws Exception {
44	        String scheduleKey = key("SCH");
45	        MvcResult created = mvc.perform(post("/api/v1/plans")
46	                        .contentType(MediaType.APPLICATION_JSON)
47	                        .content(createBody(key("REQ"), scheduleKey,
48	                                occ("G1", key("SEC"), iso(8), iso(9)),
49	                                occ("G2", key("SEC"), iso(9), iso(10)))))
50	                .andExpect(status().isCreated())
51	                .andReturn();
52	        JsonNode body = read(created);
53	        assertThat(body.get("scheduleKey").asText()).isEqualTo(scheduleKey);
54	        assertThat(body.get("version").asInt()).isEqualTo(1);
55	        assertThat(body.get("status").asText()).isEqualTo("DRAFT");
56	        assertThat(body.get("occupancies")).hasSize(2);
57	        assertThat(body.get("occupancies").get(0).get("startUtc").asText())
58	                .isEqualTo(iso(8));
59	
60	        MvcResult detail = mvc.perform(get("/api/v1/plans/{key}", scheduleKey))
61	                .andExpect(status().isOk()).andReturn();
62	        assertThat(read(detail)).isEqualTo(body);
63	    }
64	
65	    @Test
66	    void updateReplaceOccupanciesIncrementsVersion() throws Exception {
67	        String scheduleKey = key("SCH");
68	        createPlan(scheduleKey, occ("G1", key("SEC"), iso(8), iso(9)));
69	
70	        MvcResult updated = mvc.perform(put("/api/v1/plans/{key}/occupancies", scheduleKey)
71	                        .contentType(MediaType.APPLICATION_JSON)
72	                        .content(updateBody(key("REQ"), 1,
73	                                occ("G3", key("SEC"), iso(10), iso(11)))))
74	                .andExpect(status().isOk()).andReturn();
75	        JsonNode body = read(updated);
76	        assertThat(body.get("version").asInt()).isEqualTo(2);
77	        assertThat(body.get("occupancies")).hasSize(1);
78	        assertThat(body.get("occupancies").get(0).get("trainNo").asText()).isEqualTo("G3");
79	    }
