package com.example.starter.plan.model;

import java.time.LocalDate;

/**
 * 铁路走廊日计划主记录。
 *
 * @param id            主键
 * @param scheduleKey   计划业务键，全局唯一
 * @param opDate        运营日期（Asia/Shanghai 日历日）
 * @param version       版本号，草稿占用整体替换成功一次加一
 * @param status        计划状态
 * @param stockKey      车底标识，null 表示不参与车底交路链
 * @param originStation 始发站，null 表示未登记车底交路
 * @param destStation   终到站，null 表示未登记车底交路
 * @param chainState    交路链状态（NORMAL / PENDING_REPLAN）
 */
public record DayPlan(long id, String scheduleKey, LocalDate opDate, int version, PlanStatus status,
                      String stockKey, String originStation, String destStation,
                      ChainState chainState) {
}

package com.example.starter.plan.model;

/**
 * 计划在车底交路链中的状态：NORMAL 正常衔接；PENDING_REPLAN 因前序段取消导致断链，
 * 被标记为待重排，待后续发布/改签/周转参数调整使链恢复连续后清除。
 */
public enum ChainState {
    NORMAL,
    PENDING_REPLAN
}

package com.example.starter.plan.model;

/**
 * 车底登记与最小周转参数。
 *
 * @param id                   主键
 * @param stockKey             车底标识，全局唯一
 * @param minTurnaroundMinutes 最小周转分钟数（1～240）
 * @param version              周转参数版本，修改成功一次加一
 */
public record RollingStock(long id, String stockKey, int minTurnaroundMinutes, int version) {
}

package com.example.starter.plan.model;

import java.time.LocalDate;

/**
 * 车底交路断链记录，追加后不可变。
 *
 * @param id                   主键
 * @param stockKey             断链车底标识
 * @param opDate               断链发生运营日（Asia/Shanghai 日历日）
