            rs.getString("stock_key"),
            rs.getInt("min_turnaround_minutes"),
            rs.getInt("version"));

    private static final RowMapper<ChainBreak> BREAK_MAPPER = (rs, n) -> new ChainBreak(
            rs.getLong("id"),
