    // 旧计划所属车底链被移出一段：按取消处理，允许断链并记录
    recordChainBreak(oldPlan, now);
}
if (newPlan.stockKey() != null) {
    planRepo.clearPendingReplan(newPlan.stockKey(), newPlan.opDate(), now);
}

