    // ---------- 取消中间段：断链记录 + 待重排 ----------

    @Test
    void cancelMiddleSegmentWritesBreakRecordAndMarksPendingReplan() throws Exception {
        String stock = key("STK");
        createStock(stock, 30);
        String planA = key("SCH");
        String planB = key("SCH");
